-- Rega24 production data (D1 rega24-migration): the ten Rega24Travel sub-categories, 2026-11-18.
-- Same rows as src/config/travel.ts (TRAVEL_SUBCATEGORIES) and prisma/seed.ts (checked by tests/travel.test.ts).
-- Parents are the existing top-level categories travel-tickets and transport-moving; nothing else is touched.
-- ADDITIVE ONLY: inserts a category only when its key and slug are both unused and its parent exists; it never updates
-- or deletes, and running it again changes nothing. New ids start with seed_category_travel_, so the change can be
-- undone exactly (no business refers to them yet).
-- Pre-check on production 2026-11-18: 0 sub-categories in the tree, 0 categories or businesses using these slugs.
-- Undo (only rows this file created; skips any category a business, service or child already uses):
--   DELETE FROM Category WHERE id LIKE 'seed_category_travel_%' AND NOT EXISTS (SELECT 1 FROM Business b WHERE b.categoryId=Category.id) AND NOT EXISTS (SELECT 1 FROM Service s WHERE s.categoryId=Category.id) AND NOT EXISTS (SELECT 1 FROM Category c WHERE c.parentId=Category.id);
-- Apply (after a D1 Time Travel restore point is noted):
--   node scripts/project-identity-guard.mjs --project REGA && npx wrangler d1 execute rega24-migration --remote --file prisma/d1/data/20261118_travel_subcategories.sql
WITH v(k,parent,ckb,kmr,de,en,ar,fa,tr,ord) AS (VALUES ('travel-agencies','travel-tickets','نووسینگەکانی گەشت و گوزار','Ajansên rêwîtiyê','Reisebüros','Travel Agencies','وكالات السفر','آژانس‌های مسافرتی','Seyahat Acenteleri',0),('airlines-tickets','travel-tickets','کۆمپانیاکانی فڕۆکە و نووسینگەکانی بلیت','Firokexane û ofîsên bilêtan','Fluggesellschaften & Ticketbüros','Airlines & Ticket Agencies','شركات الطيران ومكاتب التذاكر','شرکت‌های هواپیمایی و دفاتر بلیت','Havayolları ve Bilet Acenteleri',1),('taxi-transfer','transport-moving','تاکسی و گواستنەوەی تایبەت','Taksî û veguhastina taybet','Taxi & Privattransfer','Taxi & Private Transfer','تاكسي ونقل خاص','تاکسی و ترانسفر خصوصی','Taksi ve Özel Transfer',2),('airport-transfer','transport-moving','گواستنەوەی فڕۆکەخانە','Veguhastina balafirgehê','Flughafentransfer','Airport Transfer','النقل من وإلى المطار','ترانسفر فرودگاهی','Havalimanı Transferi',3),('car-rental','transport-moving','کرێدانی ئۆتۆمبێل','Kirêkirina otomobîlan','Autovermietung','Car Rental','تأجير السيارات','اجاره خودرو','Araç Kiralama',4),('bus-companies','transport-moving','کۆمپانیاکانی پاس','Şîrketên otobusan','Busunternehmen','Bus Companies','شركات الحافلات','شرکت‌های اتوبوسرانی','Otobüs Firmaları',5),('moving-services','transport-moving','گواستنەوەی ماڵ و کەلوپەل','Barkirina malê','Umzugsdienste','Moving Services','خدمات نقل الأثاث','خدمات اسباب‌کشی','Evden Eve Nakliyat',6),('cargo-logistics','transport-moving','باربری و گواستنەوەی کاڵا','Kargo û lojîstîk','Fracht & Logistik','Cargo & Logistics','الشحن والخدمات اللوجستية','باربری و لجستیک','Kargo ve Lojistik',7),('courier-delivery','transport-moving','گەیاندنی پاکەت و کاڵا','Kurye û gihandin','Kurier & Lieferdienste','Courier & Delivery','البريد السريع والتوصيل','پیک و تحویل','Kurye ve Teslimat',8),('vehicle-transport','transport-moving','گواستنەوەی ئۆتۆمبێل','Veguhastina wesayîtan','Fahrzeugtransport','Vehicle Transport','نقل المركبات','حمل خودرو','Araç Taşıma',9)) INSERT INTO Category (id,key,slug,parentId,nameCkb,nameKmr,nameDe,nameEn,nameAr,nameFa,nameTr,icon,sectionKey,sortOrder,isActive,createdAt,updatedAt) SELECT 'seed_category_travel_'||k,k,k,(SELECT id FROM Category WHERE key=v.parent),ckb,kmr,de,en,ar,fa,tr,'near','businesses',ord,1,1795003200000,1795003200000 FROM v WHERE NOT EXISTS (SELECT 1 FROM Category c WHERE c.key=v.k OR c.slug=v.k) AND EXISTS (SELECT 1 FROM Category WHERE key=v.parent);
